#include <algorithm>

inline void purge(std::vector<Job>& jobs) {
  jobs.erase(std::remove_if(jobs.begin(), jobs.end(),
                            [](const Job& job) { return job.done; }),
             jobs.end());
}

#include <map>

inline void purge(std::map<JobId, Job>& jobs) {
  jobs.erase(std::remove_if(jobs.begin(), jobs.end(),
                            [](const auto& entry) { return entry.second.done; }),
             jobs.end());
}

inline void purge(std::map<JobId, Job>& jobs) {
  for (auto it = jobs.begin(); it != jobs.end();) {
    if (it->second.done) {
      it = jobs.erase(it);
    } else {
      ++it;
    }
  }
}

#include <cstddef>
#include <ranges>

template <typename Container, typename Pred>
  requires std::ranges::sized_range<Container>
inline std::size_t purge_if(Container& container, Pred pred) {
  const auto before = container.size();
  std::erase_if(container, pred);
  return before - container.size();
}
